with open('gwas-catalog-studies-download-alternative-v1.0.2.1.txt', newline='', encoding='utf-8') as f:
    for row in csv.DictReader(f, delimiter='\\t'):
        if row['PUBMEDID']=='40770095' and row['FULL SUMMARY STATISTICS']=='yes':
            loc=row['SUMMARY STATS LOCATION'].replace('http://','https://')
            acc=row['STUDY ACCESSION']
            rows.append((acc,row['DISEASE/TRAIT'],loc + f'/harmonised/{acc}.h.tsv.gz'))
print('candidates',len(rows), flush=True)

def query(item):
    acc,trait,url=item
    try:
        res=subprocess.run(['tabix',url,'1:161530617-161530617'], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=30)
        if res.returncode"'!=0 or not res.stdout.strip():
            return None
        vals=[]
        for line in res.stdout.strip().splitlines():
            parts=line.split('"'\\t')
            if len(parts)>=8:
                try: p=float(parts[7])
                except: continue
                vals.append((p,line))
        if not vals: return None
        best=min(vals,key=lambda x:x[0])
        return acc,trait,best[0],best[1]
    except Exception as e:
        return None

found=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=24) as ex:
    futs={ex.submit(query,item):item for item in rows}
    done=0
    for fut in concurrent.futures.as_completed(futs):
        done+=1
        r=fut.result()
